fun claim_rebates_clears_record_test() {
    let mut scenario = ts::begin(ADMIN);
    random::create_for_testing(scenario.ctx());

    let mut referral = new(
        500,  // referrer_discount_bps: 5%
        400,  // referee_discount_bps: 4%
        10_000, // referrer_deposit_usd_threshold: $10000
        scenario.ctx()
    );

    // generate referral code and process rebate
    referral.set_accumulated_deposit_usd_for( USER1, 10_001);
    scenario.next_tx( USER1);
    let referral_code = {
        let random = scenario.take_shared<Random>();
        referral.generate_referral_code( &random, scenario.ctx());
        let code = referral.get_referral_code( USER1);
        ts::return_shared(random);
        code
    };

    // process rebate twice to accumulate records
    scenario.next_tx(USER2);
    {
        let mut fee1 = coin::mint_for_testing<USDC>(1000, scenario.ctx());
        fee1 = referral.track_flash_loan_usage<USDC>(fee1, referral_code, USER2, scenario.ctx());
        std::unit_test::destroy(fee1);
    };

    scenario.next_tx( USER2);
    {
        let mut fee2 = coin::mint_for_testing<USDC>(1000, scenario.ctx());
        fee2 = referral.track_flash_loan_usage<USDC>(fee2, referral_code, USER2, scenario.ctx());
        std::unit_test::destroy(fee2);
    };

    // check that record shows accumulated amount
    let (coin_types, amounts) = referral.list_rebates(USER2);
    assert!(coin_types.length() == 1, 0);
    let amount = *amounts.borrow( 0);
    assert!(amount == 2 * 1000 * 400 / 10_000, 1); // accumulated

    // claim rebates
    scenario.next_tx( USER2);
    {
        let rebate_coin = referral.claim_rebates<USDC>( scenario.ctx());
        let rebate_amount = rebate_coin.value();
        assert!(rebate_amount == 2 * 1000 * 400 / 10_000, 2);
        std::unit_test::destroy(rebate_coin);
    };

    // heck that record is now 0
    let (coin_types, amounts) = referral.list_rebates( USER2);
    assert!(coin_types.length() == 0, 3);
    assert!(amounts.length() == 0, 3);

    std::unit_test::destroy(referral);
    ts::end(scenario);
}

